def validate_public_url(url):
    u = urlparse(url)
    if u.scheme != "https" or not u.hostname or u.port not in (None, 443):
        raise Invalid("bad url")
    ips = {ai[4][0] for ai in socket.getaddrinfo(u.hostname, 443, type=socket.SOCK_STREAM)}
    for ip in map(ipaddress.ip_address, ips):
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
            raise Invalid("non-public address")
    return u.hostname, sorted(ips)[0], u.path or "/"

def fetch_logo(url):
    host, ip, path = validate_public_url(url)
    s = PinnedSession(host, ip)  # connects to ip, verifies the TLS cert for host
    r = s.get(f"https://{host}{path}", timeout=3, allow_redirects=False, stream=True)
    return r.raw.read(1_048_576, decode_content=True)

